from author import C,M,P,S

c=C('运算符与输入输出')
S(c,'常见运算与计算顺序',M('total := 80 + 90*2\ngrouped := (80 + 90) * 2\nfmt.Println(total)\nfmt.Println(grouped)\nfmt.Println(17 % 5)'),[
 P([2,3], '加减乘除让原来的数值得到新的结果。第一行先做九十乘二，再加八十，因为乘法通常先于加法。第二行用小括号要求先算括号里面，所以顺序不同。程序中的乘法使用星号，除法使用斜线。初学时不确定顺序，就加上表达意图的小括号，不要让读者靠猜测理解你的计算。'),
 P([4,5,6], '前两项分别得到二百六十和三百四十。最后的百分号在这里表示取余数，不是百分比。十七除以五，可以完整分成三组，还剩二，因此输出二。余数可以用于判断奇偶，或决定每隔几轮做一次事情。这里先使用非负整数理解含义；遇到负数和溢出等情况，还要另外核对规则。先说清每一步正在计算什么，比看到错误就随便换符号更有效。',True)],['先乘除，后加减','括号明确计算顺序','百分号在这里表示余数'],'260\n340\n2')
S(c,'比较与逻辑运算',M('score := 85\nattended := true\nfmt.Println(score >= 60)\nfmt.Println(score >= 60 && attended)\nfmt.Println(score < 60 || !attended)'),[
 P([2,4], '程序可以比较两个值，得到真或假的结果。成绩是否至少六十，就是一个比较。判断相等使用两个等号，赋值则使用一个等号，两者作用不同。这里的比较不会修改成绩，而是在提出一个问题。真假结果可以直接输出，也可以交给后面要学的条件判断。Go 的条件需要明确的布尔值，不能随便拿整数代替真假。'),
 P([3,5,6], '两个与号表示并且，两边都为真才成立。两个竖线表示或者，至少一边为真就成立。感叹号把真假反过来。这里成绩及格，而且到场，所以第二条也为真；没有不及格，也没有缺席，所以最后为假。条件太复杂时，可以先分别保存几个有意义的小条件，再把它们组合。看得懂每个小问题，比把所有逻辑挤成一大行更容易排查。',True)],['两个等号判断相等','并且、或者、取反组合条件','比较结果是 bool'],'true\ntrue\nfalse')
S(c,'让输出格式更清楚',M('name := "小林"\nscore := 85\naverage := 86.26\nfmt.Printf("%s：%d 分\\n", name, score)\nfmt.Printf("平均分：%.1f\\n", average)'),[
 P([2,3,5], 'Println 适合快速显示几个值。想把姓名、分数和说明排成固定格式，可以使用 Printf。第一个参数是格式文字，百分号后面的小写 s 对应字符串，小写 d 对应整数。后面的参数按照这些位置依次填进去。格式和数据数量、类型应当对应，不要把所有格式符都当成可以随便替换的装饰。'),
 P([4,6], '输出小数时，点一加小写 f 表示这里保留一位小数显示，于是八十六点二六显示为八十六点三。格式化只改变这一次的显示，不会把原来的 average 永久改成这个值。若以后还要用原值继续计算，它仍然保留原来的数值。另外，Printf 不会自动加换行，反斜线加 n 是这里主动写出的换行。想清楚显示和数据本身的区别，可以避免很多误解。',True)],['Printf 按格式填入数据','显示精度不改变原变量','换行由反斜线 n 明确给出'],'小林：85 分\n平均分：86.3')
S(c,'读取键盘输入',M('var name string\ncount, err := fmt.Scan(&name)\nif err != nil {\n    fmt.Println("输入失败")\n    return\n}\nfmt.Println(count, name)'),[
 P([2,3], '之前的数据都写在源代码里，现在让使用程序的人输入。先准备保存姓名的变量，再调用 Scan。名字前面的与号表示把这个变量的位置交给输入工具，让它把读到的内容写进去。这里先认识这个用途，指针一章会进一步解释。Scan 会把输入按空白分开读取，所以这个例子适合一个不含空格的姓名，不是一次读入任意长的整行文章。'),
 P([4,5,6,8], 'Scan 会交回两个结果，一个说明成功读取了多少项，另一个说明是否发生错误。先看到的 if 是错误检查，下一章会详细讲它。err 不是 nil 时，显示输入失败并结束，避免把失败后的结果当成正常数据继续使用。假设输入小林，读取一项成功，就输出一和小林。Go 中不少操作会同时返回结果和错误，我们会逐步把这种写法读熟。',True)],['Scan 读取按空白分隔的数据','与号提供写入变量的位置','先检查错误，再使用结果'],'1 小林',stdin='小林\n')
S(c,'读取整数并检查成功与否',M('var score int\ncount, err := fmt.Scan(&score)\nif err != nil || count != 1 {\n    fmt.Println("请输入整数")\n    return\n}\nfmt.Println(score + 5)'),[
 P([2,3], '如果提前声明的目标变量是 int，Scan 就按整数读取，不需要先手动保存成字符串。这里准备一份成绩，读取一项数据。输入的内容必须符合整数格式。把目标变量的类型写清楚，就相当于告诉输入工具这一次需要怎样的数据；但使用者是否真的照要求输入，程序仍然必须检查。'),
 P([4,5,6,8], '条件的意思是，发生错误，或者没有成功读到一项，就提示请输入整数并结束。只有检查通过，才给成绩加五并输出。输入八十会得到八十五，输入普通字母就会走提示路线。不要忽略错误结果，再把默认的零分当成用户输入的成绩。先检查、后使用，是 Go 里很值得从第一个程序就建立的习惯。',True)],['目标变量决定读取类型','检查错误和读取项数','失败时不继续使用假数据'],'85',stdin='80\n')
code=M('fmt.Println(5 / 2)\nfmt.Printf("%.1f\\n", float64(5/2))\nfmt.Printf("%.1f\\n", float64(5)/2)')
S(c,'练习：先除法，还是先转换',code,[P([2,3,4], '请预测三条输出。第二条和第三条都写了 float64，也都按一位小数显示，但转换发生的位置不同。先在纸上算出每个小括号里面的结果，再进行后续步骤。特别想清楚，整数除法丢掉的小数，能不能靠最后一次转换恢复。现在先独立思考四秒。')],['先确认除法两边的类型','注意转换发生在计算之前还是之后'],kind='question',answer='2\n2.0\n2.5')
S(c,'答案：丢掉的小数不会回来',code,[
 P([2,3], '第一条是两个整数相除，得到整数二。第二条也先进行这个整数除法，再把二转换成小数类型，按一位小数显示为二点零。转换只是把已经得到的数值换一种类型表达，不知道之前被截掉的小数是什么，也不会替我们重新做一次原本想要的除法。',True),
 P([4], '第三条先把五转成 float64，再进行这次除法，因此结果是二点五。这里的整数常量二可以按这个运算需要的类型使用，和两个已经有确定不同类型的变量混合计算，还要区分。对入门练习，先记住需要小数结果就要在计算前把类型处理好。检查一个意外结果时，沿着真实的计算顺序往前找原因，不要只盯着最后的显示格式。',True)],['整数除法先得到 2','事后转换只能得到 2.0','先转换再除法得到 2.5'],'2\n2.0\n2.5')

c=C('分支与循环')
S(c,'用 if 选择路线',M('score := 75\nif score >= 60 {\n    fmt.Println("及格")\n} else {\n    fmt.Println("继续努力")\n}'),[
 P([2,3,4], '当程序需要根据情况做决定，就用 if。这里先判断成绩是否至少六十。条件为真时，执行这一支大括号中的输出。Go 不要求给这个条件再套一对小括号，但条件结果必须是 bool。成绩是七十五，所以会走及格这一支。把条件读成一句明确的问题，有助于检查大于号和小于号有没有写反。'),
 P([5,6], '条件为假时才执行 else 的部分，这里两支不会同时输出。else 要和前面的大括号放在同一行，避免受到换行时自动补分号的规则影响。若失败时无需做任何事，可以不写 else。缩进帮助我们看层次，真正决定哪几条语句属于分支的，是大括号的范围。不要因为一行看起来缩进了，就以为它一定受上面的判断控制。',True)],['条件需要 bool','成立与不成立走不同分支','else 与前面的大括号同一行'],'及格')
S(c,'分成多档并控制变量范围',M('if score := 88; score >= 90 {\n    fmt.Println("优秀")\n} else if score >= 60 {\n    fmt.Println("及格")\n} else {\n    fmt.Println("未及格")\n}'),[
 P([2,3], '如果需要优秀、及格和未及格三档，可以用 else if 继续判断。这里第一行还带一个简短的初始化语句，先准备 score，再用分号分开后面的条件。这份变量的使用范围限定在整个判断结构中，后面的 else if 和 else 也能使用它，但判断结构结束以后就不能直接拿这个局部名字继续用。'),
 P([4,5,6,7], '八十八不够九十，就继续检查是否至少六十，成立后输出及格，不再执行后面的分支。条件的排列顺序很重要。如果把至少六十放在最前面，九十五也会先被这一项接住。分档之前先明确边界，再按适当顺序书写。用短初始化不是必须的，初学也可以先把变量声明在上面一行，等熟悉作用范围后再选更合适的写法。',True)],['else if 按顺序继续判断','可在 if 前半部分初始化变量','局部变量的范围到判断结构结束'],'及格')
S(c,'用 switch 处理多种情况',M('score := 88\nswitch {\ncase score >= 90:\n    fmt.Println("优秀")\ncase score >= 60:\n    fmt.Println("及格")\ndefault:\n    fmt.Println("未及格")\n}'),[
 P([2,3,4,5], '多种情况也可以用 switch。这里没有在 switch 后面放一个固定目标值，而是让各个 case 自己提供判断条件。程序从上往下寻找第一项成立的情况。八十八不满足第一项，就继续往下。另一个常见形式是 switch 后面写一个值，再用 case 匹配不同取值，选择哪种形式取决于问题本身。'),
 P([6,7,8,9,10], '第二项成立，输出及格。Go 中普通的 case 执行完就结束这次选择，默认不会自动接着执行下一个 case，所以这里不必在每项末尾再写 break。default 处理其他项都没有匹配的情况。不要把其他语言中对 switch 的习惯直接搬过来。本课不展开主动贯穿后续分支的特殊写法，先把默认、清楚的执行过程掌握好。',True)],['按顺序选择第一个匹配项','普通 case 不会自动继续下一项','default 处理其余情况'],'及格')
S(c,'for 的开始、条件与更新',M('for n := 1; n <= 3; n++ {\n    fmt.Println(n)\n}\nfmt.Println("完成")'),[
 P([2,3], '要重复执行一项任务，不必复制很多条语句。for 这一行分成三部分：先把 n 设为一，每轮开始前检查是否不超过三，一轮结束后再把 n 增加一。两个加号表示增加一。它在 Go 中是一条独立的更新语句，不能随意塞进其他表达式里面。先按开始、检查、执行、更新这个顺序走一轮，再继续下一轮。'),
 P([4,5], 'n 为一、二、三时，分别输出对应数字。更新成四以后，条件不成立，循环结束，再输出完成。这里循环体可能重复很多次，后面的完成只执行一次。读循环不要一下子凭印象猜结果，先列出每轮变量的值，再记录这一轮执行了什么。尤其要检查条件里是否包含等号，它会影响边界那一次是否进入循环。',True)],['开始值、继续条件、更新分开看','每轮开始前检查条件','循环结束后才执行后续语句'],'1\n2\n3\n完成')
S(c,'只按条件继续循环',M('attempts := 1\nfor attempts <= 3 {\n    fmt.Println("第", attempts, "次尝试")\n    attempts++\n}'),[
 P([2,3,4], 'Go 的 for 还有更简洁的形式，只在后面写继续条件。这里每一轮都先问尝试次数是否不超过三，成立就输出一次尝试。你不需要再寻找一个叫 while 的关键字来完成同一件事。无论写法长短，条件检查发生在哪里，哪些数据会在循环中变化，都要读清楚。'),
 P([5], '这一行让尝试次数增加，条件最终才能变成假。若忘记更新，次数可能一直是一，程序就会不停重复。for 后面什么条件都不写，也能构成持续循环，但要在里面有明确的结束设计。对于零基础练习，请同时检查开始状态、继续条件和更新动作，不要只看到屏幕在输出，就认为循环一定写对了。',True)],['for 可以只写继续条件','Go 不用 while 关键字','循环需要能走向结束的变化'],'第 1 次尝试\n第 2 次尝试\n第 3 次尝试')
S(c,'提前结束与跳过一轮',M('for n := 1; n <= 5; n++ {\n    if n == 2 { continue }\n    if n == 4 { break }\n    fmt.Println(n)\n}'),[
 P([2,3], '有时需要在中途跳转。continue 表示这一轮后面的步骤不做了，继续进行下一轮。这里 n 为二时，不执行本轮的输出，但循环没有完全结束。对于这种三段式 for，后面的更新动作仍然会执行，所以 n 还会继续变化。不要把 continue 理解为重新从头声明所有变量。'),
 P([4,5], 'break 则结束这一层循环。n 为四时直接退出，因此不会输出四，也不会继续到五。最后只显示一和三。若有多层循环，需要另外确认跳转影响的是哪一层，不要看到一个 break 就认为所有循环全部结束。入门先把一层循环的完整轨迹走熟，再去组合更复杂的嵌套结构。',True)],['continue 跳过当前轮的剩余步骤','break 结束这一层循环','逐轮记录比猜结果更稳妥'],'1\n3')
code=M('total := 0\nfor n := 1; n <= 4; n++ {\n    if n == 3 { continue }\n    total += n\n}\nfmt.Println(total)')
S(c,'练习：跳过一次累计',code,[P([2,3,4,5], '请算最后的 total。n 从一开始，条件允许它到四。第三轮会执行 continue，所以你要判断本轮加法有没有机会执行，以及第四轮是否还会到来。建议按一、二、三、四列出表格，再写每轮结束后的总和。不要把跳过一轮和结束整个循环混成一件事。')],['列出每轮 n 的取值','累计值保留在循环外'],kind='question',answer='7')
S(c,'答案：一加二再加四',code,[
 P([3,4], '第一轮加入一，第二轮加入二。第三轮 n 等于三，执行 continue，当前轮后面的加法被跳过。更新动作之后，第四轮仍然会执行。我们只是这一轮不加入三，没有把 total 清零，也没有退出整个循环。这几个动作的差别，要通过具体执行步骤去理解。'),
 P([5,7], '第四轮加入四，最后总和是七。若把 continue 换成 break，就会在第三轮直接结束，最后只累加一和二，得到三。total 放在循环外声明，才能保留已经累计的结果。如果每轮都重新初始化为零，看到的就不再是完整总和。现在你已经能控制路线和重复次数，接下来把多份成绩组织成一组数据。',True)],['三被跳过，四仍然加入','最终总和是 7','break 的结果会不同'],'7')
